import{_ as t,o as l,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-30-update-mail-template/report3_spec.md","filePath":"feature/content-task-workflow/3-6-30-update-mail-template/report3_spec.md"}'),s={name:"feature/content-task-workflow/3-6-30-update-mail-template/report3_spec.md"};function i(r,e,n,d,p,c){return l(),o("div",null,[...e[0]||(e[0]=[a('<p><strong>3.6.30 Update Mail Template</strong></p><p><strong>Function Trigger</strong></p><p>A member clicks Edit on a Mail Template row in the list.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The template&#39;s creator, or OWNER/MANAGER of the Workspace.</li><li><strong>Purpose</strong>: Keep a template&#39;s name, subject, body and attachments current.</li><li><strong>Interface</strong>: The same form as Create, pre-filled with the current values.</li><li><strong>Data Processing</strong>: The system patches only the supplied fields, re-sanitizes the body and updates <code>updatedAt</code>.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Edit Mail Template Form:</p><ul><li>Same fields as Create, pre-filled; Save / Cancel.</li><li>System templates show a read-only notice and a &quot;Use template&quot; action instead of Save.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: <code>templateId</code> (path param).</li><li><strong>Input optional</strong>: <code>name</code>, <code>subject</code>, <code>bodyHtml</code>, <code>attachmentIds[]</code> — any subset (PATCH semantics).</li><li><strong>System data</strong>: <code>mail_templates</code> document.</li><li><strong>Output</strong>: the updated template.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>Only the creator or OWNER/MANAGER may update; a CREATOR cannot edit another member&#39;s template.</li><li>System templates cannot be modified from a Workspace (Admin only, via the admin API).</li><li>Updating a template never changes batches that were already sent or scheduled (they hold a snapshot).</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Not permitted → 403 <code>FORBIDDEN</code>.</li><li>System template → 403 <code>SYSTEM_TEMPLATE_READ_ONLY</code>.</li><li>Not found / deleted → 404 <code>TEMPLATE_NOT_FOUND</code>.</li><li>Provided <code>subject</code> or <code>bodyHtml</code> empty → 400 <code>VALIDATION_ERROR</code>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>A member clicks Edit on a row.</li></ol></li><li><ol start="2"><li>The member changes the fields.</li></ol></li><li><ol start="3"><li>The system validates, sanitizes and persists the change.</li></ol></li><li><ol start="4"><li>The list refreshes with the updated template.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller lacks permission → 403 <code>FORBIDDEN</code>.</li><li>3.a2: System template → 403 <code>SYSTEM_TEMPLATE_READ_ONLY</code>.</li><li>3.a3: Template missing → 404 <code>TEMPLATE_NOT_FOUND</code>.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The targeted <code>mail_templates</code> document is updated in place; existing batches are unaffected.</li></ul>',14)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
